import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';

// Per-post, per-locale request state. The translation itself lives on the Post
// model so it survives the stream re-creating component instances.
const pending = new Set();
const errors = new Set();
const localeOf = () => String(app.data.locale || 'en').split('-')[0].toLowerCase();
const keyFor = (post, locale) => `${post.id()}:${locale}`;

/**
 * On-demand translation appended under a post. Mirrors the behaviour of the
 * retired ianm/translate: translate the post into the reader's current locale,
 * cache the result server-side, and let the reader hide it again.
 */
export default class TranslationBlock extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    this.open = true;
  }
  view() {
    const post = this.attrs.post;
    const locale = localeOf();
    const detected = String(post.attribute('detectedLang') || '').split('-')[0].toLowerCase();

    // Nothing to offer when the post is already in the reader's language.
    if (detected && detected === locale) {
      return null;
    }
    if (!post.id() || post.isHidden?.()) {
      return null;
    }
    const key = keyFor(post, locale);
    const translation = post.attribute('itqanTranslation');
    const translationLocale = String(post.attribute('itqanTranslationLocale') || '').toLowerCase();
    if (translation && translationLocale === locale) {
      return m("div", {
        className: "ItqanTranslation"
      }, m("div", {
        className: "ItqanTranslation-label"
      }, app.translator.trans('itqan-translate.forum.label')), this.open && m("div", {
        className: "ItqanTranslation-text"
      }, translation), m(Button, {
        className: "Button Button--text ItqanTranslation-toggle",
        onclick: () => {
          this.open = !this.open;
          m.redraw();
        }
      }, app.translator.trans(this.open ? 'itqan-translate.forum.show_original' : 'itqan-translate.forum.show_translation')));
    }
    if (pending.has(key)) {
      return m("div", {
        className: "ItqanTranslation ItqanTranslation--loading"
      }, app.translator.trans('itqan-translate.forum.translating'));
    }
    if (errors.has(key)) {
      return m("div", {
        className: "ItqanTranslation ItqanTranslation--error"
      }, m("div", {
        className: "ItqanTranslation-text"
      }, app.translator.trans('itqan-translate.forum.error')), m(Button, {
        className: "Button Button--text ItqanTranslation-toggle",
        onclick: () => this.translate()
      }, app.translator.trans('itqan-translate.forum.translate_button')));
    }
    return m("div", {
      className: "ItqanTranslation-actions"
    }, m(Button, {
      className: "Button Button--text ItqanTranslation-button",
      icon: "fas fa-language",
      onclick: () => this.translate()
    }, app.translator.trans('itqan-translate.forum.translate_button')));
  }
  async translate() {
    const post = this.attrs.post;
    const locale = localeOf();
    const key = keyFor(post, locale);
    if (pending.has(key)) return;
    pending.add(key);
    errors.delete(key);
    m.redraw();
    try {
      const data = await app.request({
        method: 'POST',
        url: `${app.forum.attribute('apiUrl')}/itqan-translate/posts/${post.id()}`,
        body: {
          language: app.data.locale
        }
      });
      if (data && data.translation) {
        post.pushAttributes({
          itqanTranslation: data.translation,
          itqanTranslationLocale: locale
        });
      } else if (!(data && data.sameLanguage)) {
        errors.add(key);
      }
    } catch (e) {
      errors.add(key);
    } finally {
      pending.delete(key);
      m.redraw();
    }
  }
}
flarum.reg.add('itqan-translate', 'forum/components/TranslationBlock', TranslationBlock);